  if ! grep -q "^$1=" "$RES_FILE"; then
    if [ "$rc" -eq 124 ]; then write_result "__ERROR__ timeout"; else write_result "__ERROR__ rc=$rc"; fi
  fi
}
run_step HIP_VERSION     y2b_step_1 120
run_step KERNEL_COUNT    y2b_step_2 120
run_step HW_AUDIT_STATUS y2b_step_3 120

